/// `Wire` in this codec family.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct Wire {
    name: Box<[u8]>,
    lowest: u16,
    layouts: List<[u8; 32]>,
}

impl Wire {
    /// Makes a value within the given limits.
    pub fn new(limits: &Limits, parts: WireParts) -> Result<Self, Problem> {
        let WireParts { name, lowest, layouts } = parts;
        let value = Self { name, lowest, layouts };
        value.check(limits)?;
        Ok(value)
    }

    /// Reads the `name` field.
    #[must_use]
    pub fn name(&self) -> &[u8] { &self.name }

    /// Reads the `lowest` field.
    #[must_use]
    pub fn lowest(&self) -> u16 { self.lowest }

    /// Reads the `layouts` field.
    #[must_use]
    pub fn layouts(&self) -> &List<[u8; 32]> { &self.layouts }

    /// Moves the fields out without copying.
    #[must_use]
    pub fn into_parts(self) -> WireParts { WireParts { name: self.name, lowest: self.lowest, layouts: self.layouts } }

    fn check(&self, limits: &Limits) -> Result<(), Problem> {
        if self.name.len() > usize::try_from(limits.wire_name.min(CEILINGS.wire_name)).expect("u32 fits usize") { return Err(Problem { path: Path::WireName, reason: skein_codec::Reason::Bound }); }
        if !skein_codec::text_is_valid(self.name.as_ref()) { return Err(Problem { path: Path::WireName, reason: skein_codec::Reason::Utf8 }); }
        if self.layouts.capacity() > limits.wire_layouts.min(CEILINGS.wire_layouts) { return Err(Problem { path: Path::WireLayouts, reason: skein_codec::Reason::Bound }); }
        Ok(())
    }
}

